float orbit_heading =
    creature_pool[creature_index].orbit_angle
    + creature_pool[creature_index].heading;
*(creature_vec2_t *)&creature_pool[
    creature_index
].target_x =
    *(creature_vec2_t *)&creature_pool[
        linked_index
    ].position
    + creature_vec2_t(
        (float)cos(orbit_heading),
        (float)sin(orbit_heading))
        * creature_pool[
            creature_index
        ].orbit_radius.radius;

float orbit_heading =
    creature_pool[creature_index].orbit_angle
    + creature_pool[creature_index].heading;
creature_vec2_t orbit_direction(
    (float)cos(orbit_heading),
    (float)sin(orbit_heading));
*(creature_vec2_t *)&creature_pool[
    creature_index
].target_x =
    *(creature_vec2_t *)&creature_pool[
        linked_index
    ].position
    + orbit_direction * creature_pool[
        creature_index
    ].orbit_radius.radius;

float orbit_heading =
    creature_pool[creature_index].orbit_angle
    + creature_pool[creature_index].heading;
creature_vec2_t orbit_offset =
    creature_vec2_t(
        (float)cos(orbit_heading),
        (float)sin(orbit_heading))
    * creature_pool[
        creature_index
    ].orbit_radius.radius;
*(creature_vec2_t *)&creature_pool[
    creature_index
].target_x =
    *(creature_vec2_t *)&creature_pool[
        linked_index
    ].position + orbit_offset;

float orbit_heading =
    creature_pool[creature_index].orbit_angle
    + creature_pool[creature_index].heading;
creature_vec2_t orbit_target =
    *(creature_vec2_t *)&creature_pool[
        linked_index
    ].position
    + creature_vec2_t(
        (float)cos(orbit_heading),
        (float)sin(orbit_heading))
        * creature_pool[
            creature_index
        ].orbit_radius.radius;
*(creature_vec2_t *)&creature_pool[
    creature_index
].target_x = orbit_target;
